'use strict';

// Fixed inspector operations only. No caller-supplied expressions, synthetic
// runtime, require-from-checkout, app.getAppPath override, or browser Stop API.
// Source review candidate; never executed against Electron in this task.
const readline = require('readline');
const { EntryGate, loadBinding } = require('./entry_gate');

const IDENTITY = `(() => {
  const electron = require('electron');
  const app = electron.app;
  const archivePath = app.getAppPath();
  const main = require.cache[archivePath + '/src/main/index.js'];
  if (!app.isReady() || !main?.loaded || !globalThis.__FREEDOM_TEST_HARNESS__ ||
      globalThis.__FREEDOM_LINUX_CREDENTIALS_REMOVED__?.installed !== true) {
    return { ready: false };
  }
  const contents = electron.webContents.getAllWebContents()
    .filter((item) => item.getType() === 'window' && !item.isDestroyed());
  const expectedWindow = require('url').pathToFileURL(archivePath + '/src/renderer/index.html').href;
  if (!contents.length || contents.some((item) => item.isLoadingMainFrame()) ||
      !contents.some((item) => item.getURL().split('?')[0] === expectedWindow)) {
    return { ready: false };
  }
  const fs = require('fs');
  const raw = require('original-fs');
  const crypto = require('crypto');
  const sha = (data) => crypto.createHash('sha256').update(data).digest('hex');
  const metadata = JSON.parse(fs.readFileSync(archivePath + '/package.json', 'utf8'));
  if (raw.realpathSync(app.getPath('userData')) !== raw.realpathSync(process.env.FREEDOM_TEST_USER_DATA)) {
    throw new Error('real app userData differs from isolated profile');
  }
  const sandboxPreferences = contents.map((item) => {
    const prefs = item.getLastWebPreferences();
    return { sandbox: prefs.sandbox, nodeIntegration: prefs.nodeIntegration,
      contextIsolation: prefs.contextIsolation };
  });
  return { ready: true, identity: {
    uid: process.getuid(), gid: process.getgid(), isPackaged: app.isPackaged,
    mainLoaded: main.loaded, harnessReady: true,
    appPath: raw.realpathSync(archivePath), execPath: raw.realpathSync(process.execPath),
    asarSha256: sha(raw.readFileSync(archivePath)),
    backendSha256: sha(fs.readFileSync(archivePath + '/src/main/agent/workspace-execution/bubblewrap-backend.js')),
    main: metadata.main, versions: process.versions, sandboxPreferences,
    noSandbox: process.argv.includes('--no-sandbox') || app.commandLine.hasSwitch('no-sandbox'),
    rawArchiveIsFile: raw.statSync(archivePath).isFile()
  }};
})()`;

const QUIT = `(() => {
  const app = require('electron').app;
  if (!app.isReady() || !globalThis.__FREEDOM_TEST_HARNESS__ ||
      globalThis.__FREEDOM_LINUX_IDLE_PREPARED__?.mode !== 'idle') {
    throw new Error('real main/test harness not ready');
  }
  setImmediate(() => app.quit());
  return 'native-app-quit-scheduled';
})()`;

// Asynchronous app-owned preparation is polled via a fixed immutable result;
// Runtime.evaluate remains synchronous (awaitPromise:false), including Quit.
const PREPARE = `(() => {
  const harness = globalThis.__FREEDOM_TEST_HARNESS__;
  if (typeof harness?.prepareAgentExitScenario !== 'function' ||
      globalThis.__FREEDOM_LINUX_CREDENTIALS_REMOVED__?.installed !== true ||
      Object.hasOwn(globalThis, '__FREEDOM_LINUX_IDLE_PREPARED__')) throw new Error('idle preparation guard');
  const token = require('path').basename(process.env.FREEDOM_TEST_USER_DATA);
  Object.defineProperty(globalThis, '__FREEDOM_LINUX_IDLE_PREPARED__', {
    value: { pending: true }, configurable: true
  });
  harness.prepareAgentExitScenario({ mode: 'idle', token }).then((result) => {
    if (result.mode !== 'idle' || result.token !== token ||
        ['appOwnedService','appOwnedWorkspaceController','appOwnedProcessManager'].some(k => result[k] !== true)) {
      throw new Error('app-owned idle flags mismatch');
    }
    Object.defineProperty(globalThis, '__FREEDOM_LINUX_IDLE_PREPARED__', {
      value: Object.freeze({ ...result }), configurable: false, writable: false
    });
  }).catch(() => {
    Object.defineProperty(globalThis, '__FREEDOM_LINUX_IDLE_PREPARED__', {
      value: Object.freeze({ failed: true }), configurable: false, writable: false
    });
  });
  return 'idle-preparation-requested';
})()`;
const PREPARED = `(() => globalThis.__FREEDOM_LINUX_IDLE_PREPARED__)()`;

function validateCommand(command, connected, identified) {
  if (command.op === 'connect') {
    if (connected || !/^ws:\/\/127\.0\.0\.1:\d+\/[A-Za-z0-9-]+$/.test(command.url)) {
      throw new Error('invalid or repeated local inspector connection');
    }
    if (Object.keys(command).sort().join(',') !== 'op,url') {
      throw new Error('unexpected connect fields');
    }
  } else if (command.op === 'app-quit') {
    if (!identified || Object.keys(command).join(',') !== 'op') {
      throw new Error('Quit before verified identity or unexpected fields');
    }
  } else {
    throw new Error('unsupported fixed operation');
  }
}

// Default-context metadata alone is not proof of a Node/Electron main context.
// Probe only this fixed capability expression, with inspector command-line API
// explicitly enabled; never inject require or synthesize runtime globals.
const CONTEXT_PROBE = `(() => ({
  node: typeof process === 'object' && process.release?.name === 'node',
  browser: typeof process === 'object' && process.type === 'browser',
  electron: typeof process === 'object' && typeof process.versions?.electron === 'string',
  require: typeof require === 'function'
}))()`;

class InspectorSession {
  constructor(websocket) {
    this.websocket = websocket;
    this.nextId = 1;
    this.pending = new Map();
    this.contexts = new Map();
    this.contextId = null;
    this.invalid = false;
  }

  abort(error) {
    this.invalid = true;
    for (const waiter of this.pending.values()) waiter.reject(error);
    this.pending.clear();
  }

  receive(data) {
    try {
      if (typeof data !== 'string' || data.length > 65536) throw new Error('inspector response bound');
      const message = JSON.parse(data);
      this.entryGate?.receive(message);
      if (message.method === 'Runtime.executionContextCreated') {
        const context = message.params?.context;
        if (!context || !Number.isSafeInteger(context.id)) throw new Error('invalid execution context');
        if (this.contextId !== null && context.auxData?.isDefault === true) {
          throw new Error('default context changed after selection');
        }
        this.contexts.set(context.id, context);
      } else if (message.method === 'Runtime.executionContextDestroyed') {
        const id = message.params?.executionContextId;
        this.contexts.delete(id);
        if (id === this.contextId) throw new Error('selected Node context destroyed');
      } else if (message.method === 'Runtime.executionContextsCleared') {
        this.contexts.clear();
        throw new Error('execution contexts cleared');
      }
      const waiter = this.pending.get(message.id);
      if (!waiter) return;
      this.pending.delete(message.id);
      if (message.error || message.result?.exceptionDetails) {
        waiter.reject(new Error('fixed inspector operation failed'));
      } else {
        waiter.resolve(message.result);
      }
    } catch (error) {
      this.abort(error);
    }
  }

  request(method, params) {
    if (this.invalid) return Promise.reject(new Error('inspector session invalid'));
    return new Promise((resolve, reject) => {
      const id = this.nextId++;
      this.pending.set(id, { resolve, reject });
      try {
        this.websocket.send(JSON.stringify({ id, method, params }));
      } catch (error) {
        this.pending.delete(id);
        reject(error);
      }
    });
  }

  async initialize() {
    await this.request('Runtime.enable', {});
    const defaults = [...this.contexts.values()].filter((c) => c.auxData?.isDefault === true);
    if (this.invalid || defaults.length !== 1) throw new Error('unique default Node context required');
    this.contextId = defaults[0].id;
    const probe = await this.evaluate(CONTEXT_PROBE);
    if (!probe || ['node', 'browser', 'electron', 'require'].some((key) => probe[key] !== true)) {
      this.abort(new Error('default context is not Node/Electron main with require'));
      throw new Error('Node context capability validation failed');
    }
  }

  async evaluate(expression) {
    if (![CONTEXT_PROBE, IDENTITY, QUIT, PREPARE, PREPARED].includes(expression) || this.contextId === null) {
      throw new Error('fixed expression and selected default context required');
    }
    const response = await this.request('Runtime.evaluate', {
      expression, contextId: this.contextId, includeCommandLineAPI: true,
      returnByValue: true, awaitPromise: false,
    });
    return response?.result?.value;
  }
}

async function main() {
  let websocket;
  let identified = false;
  let quitting = false;
  let session;
  const send = (message) => process.stdout.write(`${JSON.stringify(message)}\n`);
  const deadline = setTimeout(() => {
    send({ type: 'failure', reason: 'bridge deadline' });
    process.exitCode = 1;
    session?.abort(new Error('bridge deadline'));
    websocket?.close();
  }, 26000);
  const input = readline.createInterface({ input: process.stdin });
  try {
    for await (const line of input) {
      if (line.length > 4096) throw new Error('command length bound');
      const command = JSON.parse(line);
      validateCommand(command, Boolean(websocket), identified && !quitting);
      if (command.op === 'connect') {
        websocket = new WebSocket(command.url);
        session = new InspectorSession(websocket);
        websocket.addEventListener('message', (event) => {
          session.receive(event.data);
        });
        websocket.addEventListener('close', () => {
          session.abort(new Error('inspector closed'));
          if (!quitting) send({ type: 'failure', reason: 'unexpected inspector closure' });
        });
        await new Promise((resolve, reject) => {
          websocket.addEventListener('open', resolve, { once: true });
          websocket.addEventListener('error', reject, { once: true });
        });
        await session.initialize();
        const gate = new EntryGate(session, loadBinding(), (event) => send({ type: 'entry-trace', event }));
        session.entryGate = gate;
        await gate.arm();
        while (!gate.pauses.length) {
          if (session.invalid) throw new Error('inspector invalid while waiting for entry pause');
          await new Promise((resolve) => setTimeout(resolve, 10));
        }
        await gate.installAtPause();
        for (;;) {
          const result = await session.evaluate(IDENTITY);
          if (result?.ready) {
            await session.evaluate(PREPARE);
            let prepared;
            do {
              prepared = await session.evaluate(PREPARED);
              if (prepared?.failed) throw new Error('app-owned idle preparation failed');
              if (prepared?.pending) await new Promise((resolve) => setTimeout(resolve, 10));
            } while (prepared?.pending);
            if (prepared?.mode !== 'idle' ||
                ['appOwnedService','appOwnedWorkspaceController','appOwnedProcessManager'].some((k) => prepared[k] !== true)) {
              throw new Error('missing actual app-owned idle flags');
            }
            send({ type: 'idle-prepared', prepared });
            identified = true;
            send({ type: 'identity', identity: result.identity });
            break;
          }
          await new Promise((resolve) => setTimeout(resolve, 50));
        }
      } else {
        quitting = true;
        const result = await session.evaluate(QUIT);
        if (result !== 'native-app-quit-scheduled') throw new Error('unexpected Quit acknowledgement');
        send({ type: 'quit-scheduled' });
        websocket.close(); // Let Node/Electron exit without waiting for the inspector.
      }
    }
  } finally {
    clearTimeout(deadline);
    websocket?.close();
  }
}

if (require.main === module) {
  main().catch((error) => {
    process.stdout.write(`${JSON.stringify({ type: 'failure', reason: error.message })}\n`);
    process.exitCode = 1;
  });
}

module.exports = { IDENTITY, QUIT, CONTEXT_PROBE, PREPARE, PREPARED, InspectorSession, validateCommand };

