'use strict';

const assert = require('node:assert/strict');
const { test } = require('node:test');
const vm = require('node:vm');
const { IDENTITY, QUIT, CONTEXT_PROBE, InspectorSession, validateCommand } = require('./browser_bridge');

test('fixed identity and Quit expressions parse without executing', () => {
  assert.doesNotThrow(() => new Function(`return ${IDENTITY}`));
  assert.doesNotThrow(() => new Function(`return ${QUIT}`));
});

test('only local inspector connection is accepted', () => {
  validateCommand({ op: 'connect', url: 'ws://127.0.0.1:1234/abc-123' }, false, false);
  for (const url of ['ws://remote:1234/id', 'https://127.0.0.1:1234/id', 'ws://127.0.0.1:1/id?token=x']) {
    assert.throws(() => validateCommand({ op: 'connect', url }, false, false));
  }
});

test('unknown operation or expression injection is refused', () => {
  for (const command of [{ op: 'evaluate', expression: 'x' }, { op: 'process-stop' },
    { op: 'app-quit', expression: 'x' }, { op: 'connect', url: 'ws://127.0.0.1:1/id', source: 'x' }]) {
    assert.throws(() => validateCommand(command, false, true));
  }
});

test('Quit requires established identity and cannot reconnect', () => {
  assert.throws(() => validateCommand({ op: 'app-quit' }, true, false));
  assert.throws(() => validateCommand({ op: 'connect', url: 'ws://127.0.0.1:1/id' }, true, true));
  validateCommand({ op: 'app-quit' }, true, true);
});

test('identity reads raw archive and archive-resolved source without synthetic path override', () => {
  assert.match(IDENTITY, /require\('original-fs'\)/);
  assert.match(IDENTITY, /raw\.readFileSync\(archivePath\)/);
  assert.match(IDENTITY, /main\?\.loaded/);
  assert.match(IDENTITY, /__FREEDOM_TEST_HARNESS__/);
  assert.doesNotMatch(IDENTITY, /app\.getAppPath\s*=/);
  assert.doesNotMatch(IDENTITY, /checkout|agentRuntime\s*=/);
});

// No WebSocket, Electron, files, subprocess or inspector is opened. The exact
// serialized requests are decoded and evaluated only against inert pure stubs.
function mockInspector(options = {}) {
  const wire = [];
  const deferred = [];
  const reads = [];
  let quits = 0;
  let ready = options.ready !== false;
  const app = { isReady: () => ready, getAppPath: () => '/mock/app.asar', isPackaged: true,
    getPath: () => '/mock/profile',
    commandLine: { hasSwitch: () => false }, quit: () => { quits++; } };
  const modules = {
    electron: { app, webContents: { getAllWebContents: () => [{
      getType: () => 'window', isDestroyed: () => false,
      getURL: () => options.blank ? 'about:blank' : 'file:///mock/app.asar/src/renderer/index.html',
      isLoadingMainFrame: () => options.loading === true,
      getLastWebPreferences: () => ({ sandbox: true, nodeIntegration: false, contextIsolation: true }),
    }] } },
    fs: { readFileSync: (path) => {
      reads.push(['archive', path]);
      return path.endsWith('/package.json') ? '{"main":"src/main/index.js"}' : 'mock-backend';
    } },
    'original-fs': { realpathSync: (path) => path, statSync: () => ({ isFile: () => true }),
      readFileSync: (path) => { reads.push(['raw', path]); return 'mock-raw-archive'; } },
    crypto: require('node:crypto'),
    url: require('node:url'),
  };
  const fakeRequire = (name) => {
    if (!(name in modules)) throw new Error('unexpected mock module');
    return modules[name];
  };
  fakeRequire.cache = { '/mock/app.asar/src/main/index.js': { loaded: options.loaded !== false } };
  let session;
  const socket = { send: (text) => {
    const request = JSON.parse(text);
    wire.push(request);
    if (request.method === 'Runtime.enable') {
      for (const context of options.contexts ?? [
        { id: 99, name: 'isolated', auxData: { isDefault: false } },
        { id: 17, name: 'Node mock', auxData: { isDefault: true } },
      ]) {
        session.receive(JSON.stringify({ method: 'Runtime.executionContextCreated', params: { context } }));
      }
      session.receive(JSON.stringify({ id: request.id, result: {} }));
      return;
    }
    assert.equal(request.method, 'Runtime.evaluate');
    assert.equal(request.params.contextId, 17);
    assert.equal(request.params.includeCommandLineAPI, true);
    assert.equal(request.params.returnByValue, true);
    assert.equal(request.params.awaitPromise, false);
    const sandbox = {
      process: { release: { name: 'node' }, type: options.renderer ? 'renderer' : 'browser',
        versions: { electron: 'mock' }, getuid: () => 1001, getgid: () => 1001,
        execPath: '/mock/freedom', argv: [], env: { FREEDOM_TEST_USER_DATA: '/mock/profile' } },
      setImmediate: (callback) => deferred.push(callback),
      __FREEDOM_TEST_HARNESS__: {},
      __FREEDOM_LINUX_CREDENTIALS_REMOVED__: { installed: !options.noMarker },
      __FREEDOM_LINUX_IDLE_PREPARED__: { mode: 'idle' },
    };
    if (request.params.includeCommandLineAPI && !options.noRequire) sandbox.require = fakeRequire;
    try {
      const value = vm.runInNewContext(request.params.expression, sandbox, { timeout: 100 });
      session.receive(JSON.stringify({ id: request.id, result: { result: { value } } }));
    } catch (error) {
      session.receive(JSON.stringify({ id: request.id, result: { exceptionDetails: { text: error.message } } }));
    }
  } };
  session = new InspectorSession(socket);
  return { session, wire, reads, deferred, quits: () => quits, setReady: (value) => { ready = value; } };
}

test('serialized selected-context probe, real identity expression and native Quit execute against pure stubs', async () => {
  const fixture = mockInspector();
  await fixture.session.initialize();
  const identity = await fixture.session.evaluate(IDENTITY);
  assert.equal(identity.ready, true);
  assert.equal(identity.identity.mainLoaded, true);
  assert.equal(identity.identity.appPath, '/mock/app.asar');
  assert.equal(identity.identity.asarSha256,
    require('node:crypto').createHash('sha256').update('mock-raw-archive').digest('hex'));
  assert.deepEqual(fixture.reads.find(([kind]) => kind === 'raw'), ['raw', '/mock/app.asar']);
  assert.ok(fixture.reads.some(([kind, path]) => kind === 'archive' && path.endsWith('/bubblewrap-backend.js')));
  assert.equal(await fixture.session.evaluate(QUIT), 'native-app-quit-scheduled');
  assert.equal(fixture.quits(), 0);
  fixture.deferred[0]();
  assert.equal(fixture.quits(), 1);
  assert.deepEqual(fixture.wire.map((r) => r.method),
    ['Runtime.enable', 'Runtime.evaluate', 'Runtime.evaluate', 'Runtime.evaluate']);
  assert.deepEqual(fixture.wire.slice(1).map((r) => r.params.expression), [CONTEXT_PROBE, IDENTITY, QUIT]);
  for (const request of fixture.wire.slice(1)) {
    assert.deepEqual(Object.keys(request.params).sort(),
      ['awaitPromise', 'contextId', 'expression', 'includeCommandLineAPI', 'returnByValue']);
  }
});

test('no evaluation before selection and no caller expression after selection', async () => {
  const { session } = mockInspector();
  await assert.rejects(session.evaluate(IDENTITY));
  await session.initialize();
  await assert.rejects(session.evaluate('process.exit()'));
});

test('missing or ambiguous default context fails before capability evaluation', async () => {
  for (const contexts of [[], [{ id: 17 }], [
    { id: 17, auxData: { isDefault: true } }, { id: 18, auxData: { isDefault: true } },
  ]]) {
    const { session, wire } = mockInspector({ contexts });
    await assert.rejects(session.initialize(), /unique default Node context/);
    assert.equal(wire.length, 1);
  }
});

test('default context without require or Electron main identity is refused', async () => {
  for (const options of [{ noRequire: true }, { renderer: true }]) {
    const { session, wire } = mockInspector(options);
    await assert.rejects(session.initialize(), /capability/);
    assert.equal(wire.length, 2);
    await assert.rejects(session.evaluate(IDENTITY), /invalid/);
  }
});

test('actual serialized identity keeps app, archived main and window readiness gates', async () => {
  for (const options of [{ ready: false }, { loaded: false }, { loading: true }, { blank: true }, { noMarker: true }]) {
    const fixture = mockInspector(options);
    await fixture.session.initialize();
    assert.deepEqual(await fixture.session.evaluate(IDENTITY), { ready: false });
    assert.deepEqual(fixture.reads, []);
  }
});

test('selected context destruction, clearing or replacement forbids further evaluation', async () => {
  for (const event of [
    { method: 'Runtime.executionContextDestroyed', params: { executionContextId: 17 } },
    { method: 'Runtime.executionContextsCleared' },
    { method: 'Runtime.executionContextCreated', params: { context: { id: 18, auxData: { isDefault: true } } } },
  ]) {
    const { session } = mockInspector();
    await session.initialize();
    session.receive(JSON.stringify(event));
    await assert.rejects(session.evaluate(QUIT), /invalid/);
  }
});

test('actual serialized Quit exception is not an acknowledgement', async () => {
  const fixture = mockInspector();
  await fixture.session.initialize();
  fixture.setReady(false);
  await assert.rejects(fixture.session.evaluate(QUIT), /operation failed/);
  assert.equal(fixture.deferred.length, 0);
});

test('pending evaluation rejects on context loss and synchronous send error removes waiter', async () => {
  const { session } = mockInspector();
  await session.initialize();
  session.websocket = { send: () => {} };
  const pending = session.evaluate(IDENTITY);
  session.receive(JSON.stringify({ method: 'Runtime.executionContextsCleared' }));
  await assert.rejects(pending, /cleared/);
  assert.equal(session.pending.size, 0);
  const second = mockInspector().session;
  await second.initialize();
  second.websocket = { send: () => { throw new Error('mock send failure'); } };
  await assert.rejects(second.evaluate(IDENTITY), /mock send failure/);
  assert.equal(second.pending.size, 0);
});

