'use strict';

const METHODS = Object.freeze(['decryptString', 'decryptStringAsync', 'encryptString',
  'encryptStringAsync', 'getSelectedStorageBackend', 'isAsyncEncryptionAvailable',
  'isEncryptionAvailable', 'setUsePlainTextEncryption'].sort());
const MARKER = '__FREEDOM_LINUX_CREDENTIALS_REMOVED__';

// Fixed installer called only by the reviewed inspector expression in the actual
// earliest archived entry frame. Never call the original credential methods.
function install(context, expected) {
  const { electron, fs, raw, crypto, filename, loaded, executable, versions, env, uid, gid } = context;
  const path = require('path');
  const sha = (data) => crypto.createHash('sha256').update(data).digest('hex');
  const archive = electron.app.getAppPath();
  if (process.platform !== 'linux' || uid !== 1001 || gid !== 1001 || loaded !== false ||
      filename !== expected.archive + '/src/main/index.js' ||
      archive !== expected.archive || executable !== expected.app ||
      !electron.app.isPackaged || versions.electron !== '43.0.0' || versions.modules !== '148' ||
      sha(raw.readFileSync(archive)) !== expected.archiveSha256 ||
      sha(fs.readFileSync(filename)) !== expected.mainSha256 ||
      JSON.parse(fs.readFileSync(archive + '/package.json', 'utf8')).main !== 'src/main/index.js' ||
      env.FREEDOM_TEST_MODE !== '1' || !env.TMPDIR ||
      path.dirname(env.FREEDOM_TEST_USER_DATA || '') !== env.TMPDIR ||
      !/^freedom-agent-app-exit-[a-f0-9]{24}$/.test(path.basename(env.FREEDOM_TEST_USER_DATA || ''))) {
    throw new Error('earliest real Linux packaged identity/profile mismatch');
  }
  if (Object.hasOwn(globalThis, MARKER)) throw new Error('credential-removal already installed');
  const storage = electron.safeStorage;
  if (Object.getPrototypeOf(storage) !== Object.prototype && Object.getPrototypeOf(storage) !== null) {
    throw new Error('unreviewed inherited safeStorage surface');
  }
  const descriptors = Object.getOwnPropertyDescriptors(storage);
  const actual = Object.keys(descriptors).sort();
  if (JSON.stringify(actual) !== JSON.stringify(METHODS) || Object.getOwnPropertySymbols(storage).length) {
    throw new Error('unreviewed Linux safeStorage surface');
  }
  for (const name of METHODS) {
    if (typeof descriptors[name].value !== 'function' || !descriptors[name].configurable) {
      throw new Error('safeStorage method cannot be sealed: ' + name);
    }
  }
  const denied = () => { throw new Error('credential capability unavailable for qualification'); };
  const deniedAsync = async () => { throw new Error('credential capability unavailable for qualification'); };
  const replacement = {
    decryptString: denied, encryptString: denied, setUsePlainTextEncryption: denied,
    decryptStringAsync: deniedAsync, encryptStringAsync: deniedAsync,
    isEncryptionAvailable: () => false, isAsyncEncryptionAvailable: async () => false,
    getSelectedStorageBackend: () => 'unknown',
  };
  for (const name of METHODS) {
    Object.defineProperty(storage, name, { value: replacement[name], configurable: false,
      writable: false, enumerable: descriptors[name].enumerable });
  }
  const marker = Object.freeze({ installed: true, platform: 'linux', uid, gid, filename,
    mainLoadedAtInstall: loaded, archive, archiveSha256: expected.archiveSha256,
    mainSha256: expected.mainSha256, shimSha256: expected.shimSha256,
    methods: METHODS, credentialNativeCalls: 0 });
  Object.defineProperty(globalThis, MARKER, { value: marker, configurable: false, writable: false });
  fs.writeFileSync(path.join(env.FREEDOM_TEST_USER_DATA, 'credential-removal.json'),
    JSON.stringify(marker), { flag: 'wx', mode: 0o600 });
  return marker;
}

module.exports = { METHODS, MARKER, install };

