'use strict';
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');
const MAIN_SHA = '082efede85f589e203492ec5dac9f5791aa53b30dedcaa7202784706d022324b';
const sha = (data) => crypto.createHash('sha256').update(data).digest('hex');

function validateBinding(binding) {
  if (Object.keys(binding).sort().join(',') !== 'app,archive,archiveSha256,mainBytes,mainSha256,shimSha256' ||
      typeof binding.app !== 'string' || !path.isAbsolute(binding.app) ||
      binding.archive !== path.join(path.dirname(binding.app), 'resources/app.asar') ||
      binding.mainSha256 !== MAIN_SHA || binding.mainBytes !== 31721 ||
      !/^[a-f0-9]{64}$/.test(binding.archiveSha256 || '') ||
      !/^[a-f0-9]{64}$/.test(binding.shimSha256 || '')) {
    throw new Error('sealed exact package binding missing; source-only review');
  }
  return Object.freeze({ ...binding });
}

function installerExpression(binding) {
  validateBinding(binding);
  const shim = path.join(__dirname, 'capability_removal.js');
  // The module location is fixed by this reviewed bridge, never a CDP caller field.
  return `(() => {
    if (typeof require !== 'function' || typeof __filename !== 'string' ||
        typeof module !== 'object' || module.loaded !== false ||
        __filename !== ${JSON.stringify(binding.archive + '/src/main/index.js')}) {
      throw new Error('not actual unloaded entry frame');
    }
    const raw = require('original-fs');
    const crypto = require('crypto');
    const shim = ${JSON.stringify(shim)};
    const expected = ${JSON.stringify(binding)};
    if (crypto.createHash('sha256').update(raw.readFileSync(shim)).digest('hex') !== expected.shimSha256) {
      throw new Error('capability-removal source hash mismatch');
    }
    return require(shim).install({ electron: require('electron'), fs: require('fs'), raw, crypto,
      filename: __filename, loaded: module.loaded, executable: raw.realpathSync(process.execPath),
      versions: process.versions, env: process.env, uid: process.getuid(), gid: process.getgid() }, expected);
  })()`;
}

class EntryGate {
  constructor(session, binding, record) {
    this.session = session;
    this.binding = validateBinding(binding);
    this.record = record;
    this.scripts = new Map();
    this.pauses = [];
    this.breakpoints = new Set();
    this.resumed = false;
    this.armed = false;
    this.urls = [binding.archive + '/src/main/index.js',
      pathToFileURL(binding.archive + '/src/main/index.js').href];
  }

  receive(message) {
    if (message.method === 'Debugger.scriptParsed') {
      const params = message.params;
      this.scripts.set(params.scriptId, {
        url: params.url, executionContextId: params.executionContextId,
      });
      if (!this.armed && this.urls.includes(params.url)) {
        this.session.abort(new Error('app entry parsed before both entry breakpoints armed'));
      }
    } else if (message.method === 'Debugger.paused') {
      if (this.resumed) return this.session.abort(new Error('unexpected pause after entry resume'));
      if (this.pauses.length >= 2) this.session.abort(new Error('unexpected repeated pause'));
      this.pauses.push(message.params);
      this.record({ type: 'paused', params: message.params });
    }
  }

  async arm() {
    await this.session.request('Debugger.enable', {});
    for (const url of this.urls) {
      const result = await this.session.request('Debugger.setBreakpointByUrl', { url, lineNumber: 1 });
      if (typeof result.breakpointId !== 'string') throw new Error('breakpoint not armed');
      this.breakpoints.add(result.breakpointId);
      this.record({ type: 'entry-breakpoint', url, result });
    }
    this.armed = true;
    await this.session.request('Runtime.runIfWaitingForDebugger', {});
  }

  async installAtPause() {
    if (this.session.invalid || !this.armed || this.resumed || this.pauses.length !== 1) throw new Error('entry pause not uniquely ready');
    const paused = this.pauses.shift();
    const frame = paused.callFrames?.[0];
    const scriptId = frame?.location?.scriptId;
    const script = this.scripts.get(scriptId);
    const url = script?.url;
    // No bootstrap exception is enabled in this draft. Unknown/internal pauses
    // remain paused and fail; no broad browser_init regex or speculative resume.
    if (!frame || !this.urls.includes(url) ||
        !Number.isSafeInteger(this.session.contextId) ||
        script.executionContextId !== this.session.contextId ||
        !paused.hitBreakpoints?.some((id) => this.breakpoints.has(id))) {
      throw new Error('unknown pause or not an owned archived-entry breakpoint');
    }
    const source = await this.session.request('Debugger.getScriptSource', { scriptId });
    this.record({ type: 'paused-entry-source', result: source });
    if (Buffer.byteLength(source.scriptSource || '') !== this.binding.mainBytes ||
        sha(source.scriptSource || '') !== this.binding.mainSha256) throw new Error('paused main source mismatch');
    const possible = await this.session.request('Debugger.getPossibleBreakpoints', {
      start: { scriptId, lineNumber: 0, columnNumber: 0 },
      end: { scriptId, lineNumber: 2, columnNumber: 0 }, restrictToFunction: false,
    });
    if (Buffer.byteLength(JSON.stringify(possible)) > 8192) {
      throw new Error('entry breakpoint response bound');
    }
    this.record({ type: 'possible-breakpoints', result: possible });
    const locations = [...(possible.locations || [])].sort((a, b) => a.lineNumber - b.lineNumber || a.columnNumber - b.columnNumber);
    const earliest = locations[0];
    if (!earliest || earliest.scriptId !== scriptId || earliest.lineNumber !== 1 ||
        frame.location.lineNumber !== earliest.lineNumber || frame.location.columnNumber !== earliest.columnNumber) {
      throw new Error('not earliest executable entry location');
    }
    const installed = await this.session.request('Debugger.evaluateOnCallFrame', {
      callFrameId: frame.callFrameId, expression: installerExpression(this.binding),
      includeCommandLineAPI: true, returnByValue: true,
    });
    const marker = installed?.result?.value;
    this.record({ type: 'credential-removal-marker', marker });
    if (installed.exceptionDetails || marker?.installed !== true || marker.mainLoadedAtInstall !== false ||
        marker.archiveSha256 !== this.binding.archiveSha256 || marker.shimSha256 !== this.binding.shimSha256) {
      throw new Error('immutable credential-removal marker missing');
    }
    this.resumed = true;
    await this.session.request('Debugger.resume', {});
    return marker;
  }
}

function loadBinding() {
  const binding = validateBinding(JSON.parse(fs.readFileSync(path.join(__dirname, 'binding.json'), 'utf8')));
  if (sha(fs.readFileSync(path.join(__dirname, 'capability_removal.js'))) !== binding.shimSha256) {
    throw new Error('reviewed shim changed');
  }
  return binding;
}

module.exports = { EntryGate, validateBinding, installerExpression, loadBinding };

