'use strict';
// Pure stubs only: no Electron, socket, child, namespace, pidfd or native addon.
const assert = require('node:assert/strict');
const { test } = require('node:test');
const fs = require('node:fs');
const crypto = require('node:crypto');
const vm = require('node:vm');
const { EntryGate, loadBinding, validateBinding, installerExpression } = require('./entry_gate');
const { PREPARE, PREPARED } = require('./browser_bridge');
const sha = (data) => crypto.createHash('sha256').update(data).digest('hex');
// Exact approved main bytes are passive test data, never imported or executed.
const main = fs.readFileSync(__dirname + '/fixtures/main-source.txt', 'utf8');
const shim = fs.readFileSync(__dirname + '/capability_removal.js', 'utf8');
const binding = Object.freeze({ app: '/mock/freedom', archive: '/mock/resources/app.asar',
  archiveSha256: sha('raw archive mock'), mainSha256: sha(main), mainBytes: Buffer.byteLength(main),
  shimSha256: sha(shim) });

function gateFixture(options = {}) {
  const wire = [];
  const records = [];
  const session = { invalid: false, contextId: 7, abort() { this.invalid = true; }, async request(method, params) {
    assert.equal(this.invalid, false);
    const serialized = JSON.parse(JSON.stringify({ method, params }));
    wire.push(serialized);
    if (method === 'Debugger.setBreakpointByUrl') return { breakpointId: 'bp-' + params.url };
    if (method === 'Debugger.getScriptSource') return { scriptSource: options.badSource ? 'bad' : main };
    if (method === 'Debugger.getPossibleBreakpoints' && options.largeBreakpoints) {
      return { locations: [], excess: 'x'.repeat(8192) };
    }
    if (method === 'Debugger.getPossibleBreakpoints') return { locations: [
      { scriptId: 'script', lineNumber: options.late ? 2 : 1, columnNumber: 0 },
    ] };
    if (method === 'Debugger.evaluateOnCallFrame') return { result: { value: options.badMarker ? {} : {
      installed: true, mainLoadedAtInstall: false, archiveSha256: binding.archiveSha256,
      shimSha256: binding.shimSha256,
    } } };
    return {};
  } };
  const gate = new EntryGate(session, binding, (record) => records.push(record));
  const pause = () => {
    gate.receive({ method: 'Debugger.scriptParsed', params: {
      scriptId: 'script', url: gate.urls[0], executionContextId: options.foreignContext ? 8 : 7,
    } });
    gate.receive({ method: 'Debugger.paused', params: { reason: 'other',
      hitBreakpoints: options.foreign ? ['foreign'] : ['bp-' + gate.urls[0]],
      callFrames: [{ callFrameId: 'frame', location: { scriptId: 'script', lineNumber: 1, columnNumber: 0 } }],
    } });
  };
  return { gate, session, wire, records, pause };
}

test('unbound on-disk binding refuses any runtime package claim', () => {
  const actual = loadBinding(); // Passive JSON/shim bytes only; never opens Electron.
  assert.throws(() => validateBinding({ ...actual, app: null }), /source-only/);
  assert.equal(actual.archiveSha256, '48e1ce7d054a38952138d0cdc4de1221a785e25a66491a8702c15ade438ef563');
});

test('actual entry-gate path serializes both breakpoints before release, source proof then installer then resume', async () => {
  const f = gateFixture();
  await f.gate.arm(); f.pause(); await f.gate.installAtPause();
  assert.deepEqual(f.wire.map((r) => r.method), ['Debugger.enable',
    'Debugger.setBreakpointByUrl', 'Debugger.setBreakpointByUrl', 'Runtime.runIfWaitingForDebugger',
    'Debugger.getScriptSource', 'Debugger.getPossibleBreakpoints', 'Debugger.evaluateOnCallFrame', 'Debugger.resume']);
  assert.deepEqual(f.wire.slice(1, 3).map((r) => r.params), f.gate.urls.map((url) => ({ url, lineNumber: 1 })));
  assert.deepEqual(f.wire[5].params, {
    start: { scriptId: 'script', lineNumber: 0, columnNumber: 0 },
    end: { scriptId: 'script', lineNumber: 2, columnNumber: 0 }, restrictToFunction: false,
  });
  const request = f.wire[6].params;
  assert.equal(request.callFrameId, 'frame'); assert.equal(request.includeCommandLineAPI, true);
  assert.equal(request.returnByValue, true); assert.equal(request.expression, installerExpression(binding));
  assert.doesNotThrow(() => new vm.Script(request.expression));
  assert.match(request.expression, /module.loaded !== false/);
  assert.match(request.expression, /capability-removal source hash mismatch/);
  assert.equal(f.records.find((r) => r.type === 'paused-entry-source').result.scriptSource, main);
  await assert.rejects(f.gate.installAtPause());
  f.gate.receive({ method: 'Debugger.paused', params: {} });
  assert.equal(f.session.invalid, true);
});

test('source mismatch, non-earliest location, foreign pause and missing marker never resume', async () => {
  for (const options of [{ badSource: true }, { late: true }, { foreign: true }, { badMarker: true },
    { foreignContext: true }, { largeBreakpoints: true }]) {
    const f = gateFixture(options); await f.gate.arm(); f.pause();
    await assert.rejects(f.gate.installAtPause());
    assert.equal(f.wire.some((r) => r.method === 'Debugger.resume'), false);
  }
});

test('entry in another or no selected context refuses before reading source or installing capabilities', async () => {
  for (const contextId of [null, undefined, 8]) {
    const f = gateFixture(); await f.gate.arm(); f.pause(); f.session.contextId = contextId;
    await assert.rejects(f.gate.installAtPause());
    assert.equal(f.wire.some((r) => r.method === 'Debugger.getScriptSource'), false);
    assert.equal(f.wire.some((r) => r.method === 'Debugger.evaluateOnCallFrame'), false);
    assert.equal(f.wire.some((r) => r.method === 'Debugger.resume'), false);
  }
});

test('already parsed app before arming, duplicate pause and unknown bootstrap fail closed', async () => {
  const early = gateFixture(); early.pause(); assert.equal(early.session.invalid, true);
  const duplicate = gateFixture(); await duplicate.gate.arm();
  duplicate.pause(); duplicate.pause(); await assert.rejects(duplicate.gate.installAtPause());
  const unknown = gateFixture(); await unknown.gate.arm();
  unknown.gate.receive({ method: 'Debugger.paused', params: { reason: 'Break on start', callFrames: [] } });
  await assert.rejects(unknown.gate.installAtPause(), /unknown pause/);
  assert.equal(unknown.wire.some((r) => r.method === 'Debugger.resume'), false);
});

function shimFixture(options = {}) {
  const sandbox = { module: { exports: {} }, require, process: { platform: 'linux' } };
  vm.createContext(sandbox);
  vm.runInContext(shim, sandbox, { timeout: 100 });
  const exports = sandbox.module.exports;
  const storage = Object.create(null);
  let nativeCalls = 0;
  for (const method of exports.METHODS) Object.defineProperty(storage, method, {
    value: () => { nativeCalls++; throw Error('native must never be called'); }, configurable: true, enumerable: true,
  });
  if (options.extra) storage.unknownNative = () => {};
  if (options.inherited) Object.setPrototypeOf(storage, { inheritedNative() {} });
  if (options.locked) Object.defineProperty(storage, 'encryptString', { configurable: false });
  const writes = [];
  const context = { electron: { app: { getAppPath: () => binding.archive, isPackaged: true }, safeStorage: storage },
    fs: { readFileSync: (name) => name.endsWith('/package.json') ? '{"main":"src/main/index.js"}' : main,
      writeFileSync: (...args) => writes.push(args) },
    raw: { readFileSync: () => 'raw archive mock' }, crypto,
    filename: binding.archive + '/src/main/index.js', loaded: options.loaded ?? false, executable: binding.app,
    versions: { electron: '43.0.0', modules: '148' }, uid: 1001, gid: 1001,
    env: { FREEDOM_TEST_MODE: '1', TMPDIR: '/mock/tmp',
      FREEDOM_TEST_USER_DATA: '/mock/tmp/freedom-agent-app-exit-' + 'a'.repeat(24) },
  };
  return { exports, sandbox, storage, writes, context, nativeCalls: () => nativeCalls };
}

test('actual shim installs immutable marker and removes all eight capabilities with zero native calls', async () => {
  const f = shimFixture(); const marker = f.exports.install(f.context, binding);
  assert.equal(marker.installed, true); assert.equal(Object.isFrozen(marker), true);
  assert.equal(f.storage.isEncryptionAvailable(), false);
  assert.equal(await f.storage.isAsyncEncryptionAvailable(), false);
  assert.equal(f.storage.getSelectedStorageBackend(), 'unknown');
  for (const name of ['encryptString', 'decryptString', 'setUsePlainTextEncryption']) assert.throws(() => f.storage[name]('mock'));
  for (const name of ['encryptStringAsync', 'decryptStringAsync']) await assert.rejects(f.storage[name]('mock'));
  assert.equal(f.nativeCalls(), 0); assert.equal(f.writes.length, 1);
  assert.equal(f.writes[0][2].flag, 'wx'); assert.equal(f.writes[0][2].mode, 0o600);
  for (const name of f.exports.METHODS) assert.equal(Object.getOwnPropertyDescriptor(f.storage, name).writable, false);
  assert.equal(Object.getOwnPropertyDescriptor(f.sandbox, f.exports.MARKER).configurable, false);
  assert.throws(() => f.exports.install(f.context, binding), /already installed/);
});

test('loaded main, unknown inherited/own surfaces and locked methods refuse without probing natives', () => {
  for (const options of [{ loaded: true }, { extra: true }, { inherited: true }, { locked: true }]) {
    const f = shimFixture(options);
    assert.throws(() => f.exports.install(f.context, binding));
    assert.equal(f.nativeCalls(), 0); assert.equal(f.writes.length, 0);
  }
});

test('actual serialized call-frame installer validates fixed shim bytes and unloaded real frame in pure VM', () => {
  for (const mode of ['valid', 'changed-shim', 'loaded', 'wrong-frame']) {
    const f = shimFixture();
    const frameRequire = (name) => {
      if (name === 'original-fs') return { realpathSync: (p) => p,
        readFileSync: (p) => p === __dirname + '/capability_removal.js'
          ? (mode === 'changed-shim' ? 'changed' : shim) : 'raw archive mock' };
      if (name === 'crypto') return crypto;
      if (name === 'fs') return f.context.fs;
      if (name === 'electron') return f.context.electron;
      if (name === __dirname + '/capability_removal.js') return f.exports;
      throw new Error('unexpected caller module');
    };
    const sandbox = { require: frameRequire, __filename: mode === 'wrong-frame' ? '/checkout/main.js' : f.context.filename,
      module: { loaded: mode === 'loaded' }, process: { execPath: binding.app, versions: f.context.versions,
        env: f.context.env, getuid: () => 1001, getgid: () => 1001 } };
    const run = () => vm.runInNewContext(installerExpression(binding), sandbox, { timeout: 100 });
    if (mode === 'valid') assert.equal(run().installed, true); else assert.throws(run);
    assert.equal(f.nativeCalls(), 0); assert.equal(f.writes.length, mode === 'valid' ? 1 : 0);
  }
});

test('fixed serialized preparation invokes direct app-owned binding with exact idle token then freezes actual flags', async () => {
  const token = 'freedom-agent-app-exit-' + 'a'.repeat(24);
  for (const valid of [true, false]) {
    const calls = [];
    const sandbox = { require, process: { env: { FREEDOM_TEST_USER_DATA: '/mock/tmp/' + token } },
      __FREEDOM_LINUX_CREDENTIALS_REMOVED__: { installed: true },
      __FREEDOM_TEST_HARNESS__: { prepareAgentExitScenario: async (request) => {
        calls.push(request); return { mode: request.mode, token: request.token,
          appOwnedService: valid, appOwnedWorkspaceController: true, appOwnedProcessManager: true };
      } },
    };
    vm.createContext(sandbox);
    assert.equal(vm.runInContext(PREPARE, sandbox), 'idle-preparation-requested');
    await Promise.resolve(); await Promise.resolve();
    const result = vm.runInContext(PREPARED, sandbox);
    assert.equal(JSON.stringify(calls), JSON.stringify([{ mode: 'idle', token }]));
    assert.equal(Object.isFrozen(result), true);
    if (valid) assert.equal(result.appOwnedService, true); else assert.equal(result.failed, true);
  }
});

